const DEFAULT_MODEL_KEY = 'antigravity-claude-sonnet-4-6';

function resolveModel(requestedModel) {
  if (!requestedModel || requestedModel === 'antigravity') {
    return { key: DEFAULT_MODEL_KEY, ...MODEL_MAP[DEFAULT_MODEL_KEY] };
  }
  if (MODEL_MAP[requestedModel]) return { key: requestedModel, ...MODEL_MAP[requestedModel] };
  // Try partial match (e.g. "claude-sonnet" matches "claude-sonnet-4.6")
  const lower = requestedModel.toLowerCase();
  for (const [k, v] of Object.entries(MODEL_MAP)) {
    if (k.includes(lower) || lower.includes(k)) return { key: k, ...v };
  }
  return { key: DEFAULT_MODEL_KEY, ...MODEL_MAP[DEFAULT_MODEL_KEY] };
}

module.exports = { MODEL_MAP, DEFAULT_MODEL_KEY, resolveModel };

'use strict';

const { MODEL_MAP } = require('../models');
const { sendJson } = require('../utils');

// ─────────────────────────────────────────────
// GET /v1/models
// ─────────────────────────────────────────────

async function handleModels(ctx, req, res) {
  const data = Object.entries(MODEL_MAP)
    .filter(([, m]) => !m.hidden)
    .map(([id, m]) => ({
      id,
      object: 'model',
      created: 1700000000,
      owned_by: m.owned_by,
    }));
  sendJson(res, 200, { object: 'list', data });
}

module.exports = { handleModels };

'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { isLocalhostOrigin } = require('../src/server');

describe('isLocalhostOrigin', () => {
  // ── Allowed origins ──
  it('allows http://localhost', () => {
    assert.equal(isLocalhostOrigin('http://localhost'), true);
  });

  it('allows http://localhost:3000', () => {
    assert.equal(isLocalhostOrigin('http://localhost:3000'), true);
  });

  it('allows http://localhost:8080', () => {
    assert.equal(isLocalhostOrigin('http://localhost:8080'), true);
  });

  it('allows http://127.0.0.1', () => {
    assert.equal(isLocalhostOrigin('http://127.0.0.1'), true);
  });

  it('allows http://127.0.0.1:5173', () => {
    assert.equal(isLocalhostOrigin('http://127.0.0.1:5173'), true);
  });

  // ── Rejected origins ──
  it('rejects https://evil.com', () => {
    assert.equal(isLocalhostOrigin('https://evil.com'), false);
  });

  it('rejects http://evil.com', () => {
    assert.equal(isLocalhostOrigin('http://evil.com'), false);
  });

  it('rejects https://localhost (wrong protocol)', () => {
    assert.equal(isLocalhostOrigin('https://localhost'), false);
  });

  it('rejects https://localhost:3000 (wrong protocol)', () => {
    assert.equal(isLocalhostOrigin('https://localhost:3000'), false);
  });

  it('rejects http://localhost.evil.com (subdomain attack)', () => {
    assert.equal(isLocalhostOrigin('http://localhost.evil.com'), false);
  });

  it('rejects http://0.0.0.0', () => {
    assert.equal(isLocalhostOrigin('http://0.0.0.0'), false);
  });

  it('rejects null', () => {
    assert.equal(isLocalhostOrigin(null), false);
  });

  it('rejects undefined', () => {
    assert.equal(isLocalhostOrigin(undefined), false);
  });

  it('rejects empty string', () => {
    assert.equal(isLocalhostOrigin(''), false);
  });

  it('rejects malformed URL', () => {
    assert.equal(isLocalhostOrigin('not-a-url'), false);
  });
});

'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { parseRetryAfter, extractProviderError } = require('../src/utils');

describe('parseRetryAfter', () => {
  it('parses seconds-only format', () => {
    assert.equal(parseRetryAfter('reset after 45s'), 47); // 45 + 2
  });

  it('parses minutes and seconds format', () => {
    assert.equal(parseRetryAfter('reset after 42m41s'), 2563); // (42 * 60) + 41 + 2
  });

  it('parses short lengths but enforces a minimum of 10 seconds', () => {
    assert.equal(parseRetryAfter('reset after 5ms'), 10); // 5+2=7, falls back to min 10
  });

  it('enforces a minimum of 10 seconds', () => {
    assert.equal(parseRetryAfter('reset after 2s'), 10);
  });

  it('returns default 10 seconds if no match', () => {
    assert.equal(parseRetryAfter('quota exhausted'), 10);
    assert.equal(parseRetryAfter(null), 10);
    assert.equal(parseRetryAfter({}), 10);
  });
});

describe('extractProviderError', () => {
  it('extracts nested JSON message string', () => {
    const raw = 'HTTP 500: {"code":"unknown","message":"RESOURCE_EXHAUSTED (code 429): You have exhausted..."}';
    assert.equal(extractProviderError(raw), 'RESOURCE_EXHAUSTED (code 429): You have exhausted...');
  });

  it('returns raw message if not JSON', () => {
    const raw = 'HTTP 502: Bad Gateway';
    assert.equal(extractProviderError(raw), 'HTTP 502: Bad Gateway');
  });

  it('returns raw message if JSON has no message property', () => {
    const raw = 'HTTP 500: {"error":"something went wrong"}';
    assert.equal(extractProviderError(raw), raw);
  });

  it('returns fallback string for non-string input', () => {
    assert.equal(extractProviderError(null), 'null');
    assert.equal(extractProviderError(undefined), 'undefined');
    assert.equal(extractProviderError({}), '[object Object]');
  });
});

'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { extractText } = require('../src/images');

describe('extractText', () => {
  // ── String inputs ──
  it('returns plain string as-is', () => {
    assert.equal(extractText('hello world'), 'hello world');
  });

  it('returns empty string for empty string input', () => {
    assert.equal(extractText(''), '');
  });

  // ── Null / undefined / falsy inputs ──
  it('returns empty string for null', () => {
    assert.equal(extractText(null), '');
  });

  it('returns empty string for undefined', () => {
    assert.equal(extractText(undefined), '');
  });

  it('returns empty string for 0', () => {
    assert.equal(extractText(0), '');
  });

  it('returns empty string for false', () => {
    assert.equal(extractText(false), '');
  });

  // ── Array inputs (content-parts) ──
  it('extracts text from content-parts array with type=text', () => {
    const content = [
      { type: 'text', text: 'Hello' },
      { type: 'text', text: 'World' },
    ];
    assert.equal(extractText(content), 'Hello\nWorld');
  });

  it('skips image_url parts in content-parts array', () => {
    const content = [
      { type: 'text', text: 'Describe this:' },
      { type: 'image_url', image_url: { url: 'data:image/png;base64,abc' } },
      { type: 'text', text: 'What is it?' },
    ];
    assert.equal(extractText(content), 'Describe this:\nWhat is it?');
  });

  it('handles mixed string and object parts in array', () => {
    const content = ['plain string', { type: 'text', text: 'object text' }];
    assert.equal(extractText(content), 'plain string\nobject text');
  });

  it('returns empty string for empty array', () => {
    assert.equal(extractText([]), '');
  });

  it('serializes objects without text property as JSON', () => {
    const content = [{ type: 'custom', data: 42 }];
    const result = extractText(content);
    assert.equal(result, JSON.stringify({ type: 'custom', data: 42 }));
  });

  it('handles objects with text property but no type', () => {
    const content = [{ text: 'fallback text' }];
    assert.equal(extractText(content), 'fallback text');
  });

  it('coerces numeric array elements to string', () => {
    const content = [42, 0];
    // 0 becomes '0' which has length > 0, and 42 becomes '42'
    assert.equal(extractText(content), '42\n0');
  });

  it('filters out empty strings from results', () => {
    const content = [
      { type: 'text', text: 'keep' },
      { type: 'text', text: '' }, // empty text, should be filtered after map
    ];
    // empty text returns '' from p.text, which is falsy so it falls through
    // p.text is '' which is falsy, so it goes to try JSON.stringify
    const result = extractText(content);
    assert.ok(result.includes('keep'));
  });

  // ── Object inputs (non-array) ──
  it('returns text property from plain object', () => {
    assert.equal(extractText({ text: 'object text' }), 'object text');
  });

  it('serializes object without text property', () => {
    const obj = { role: 'user', data: 'test' };
    assert.equal(extractText(obj), JSON.stringify(obj));
  });

  // ── Other types ──
  it('coerces number to string', () => {
    assert.equal(extractText(123), '123');
  });

  it('coerces boolean true to string', () => {
    assert.equal(extractText(true), 'true');
  });
});

'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { getPlatformStrategy, SIDECAR_BINARY_NAMES, encodeWorkspaceId } = require('../src/sidecar/discovery');

describe('getPlatformStrategy', () => {
  it('uses explicit Apple Silicon-aware binary names on darwin', () => {
    const result = getPlatformStrategy('darwin');

    assert.equal(result.platform, 'darwin');
    assert.deepEqual(result.binaryNames, ['language_server_macos_arm', 'language_server_macos']);
    assert.equal(result.primaryBinaryName, 'language_server_macos_arm');
  });

  it('uses the Windows binary only on win32', () => {
    const result = getPlatformStrategy('win32');

    assert.equal(result.platform, 'win32');
    assert.deepEqual(result.binaryNames, ['language_server_windows_x64.exe']);
    assert.equal(result.primaryBinaryName, 'language_server_windows_x64.exe');
  });

  it('keeps the exported platform binary map in sync', () => {
    assert.deepEqual(SIDECAR_BINARY_NAMES.darwin, ['language_server_macos_arm', 'language_server_macos']);
    assert.deepEqual(SIDECAR_BINARY_NAMES.win32, ['language_server_windows_x64.exe']);
    assert.deepEqual(SIDECAR_BINARY_NAMES.linux, ['language_server_linux']);
  });

  it('throws for unsupported platforms', () => {
    assert.throws(() => getPlatformStrategy('freebsd'), /Unsupported platform/);
  });
});

describe('encodeWorkspaceId', () => {
  it('encodes a Windows path with drive letter (real observed example)', () => {
    // Observed: PID 309976 had --workspace_id file_x_3A_code_marcodiniz_ag_local_bridge
    assert.equal(
      encodeWorkspaceId('x:\\code\\marcodiniz\\ag-local-bridge'),
      'file_x_3A_code_marcodiniz_ag_local_bridge',
    );
  });

  it('encodes a Windows path supplied with forward slashes', () => {
    assert.equal(encodeWorkspaceId('x:/code/marcodiniz/ag-local-bridge'), 'file_x_3A_code_marcodiniz_ag_local_bridge');
  });

  it('encodes a second Windows workspace (MetePower)', () => {
    // Observed: PID 228604 had --workspace_id file_x_3A_code_marcodiniz_MetePower
    assert.equal(encodeWorkspaceId('x:\\code\\marcodiniz\\MetePower'), 'file_x_3A_code_marcodiniz_MetePower');
  });

  it('is case-insensitive safe — uppercase drive letter normalises identically', () => {
    // Drive letter casing must not break disambiguation; callers compare toLowerCase()
    const lower = encodeWorkspaceId('x:\\code\\project');
    const upper = encodeWorkspaceId('X:\\code\\project');
    assert.equal(lower.toLowerCase(), upper.toLowerCase());
  });

  it('encodes a macOS/Linux absolute path', () => {
    assert.equal(encodeWorkspaceId('/home/user/my-project'), 'file_home_user_my_project');
  });

  it('strips a leading slash before encoding', () => {
    // '/home/user/proj' and 'home/user/proj' should yield the same result
    assert.equal(encodeWorkspaceId('/home/user/proj'), encodeWorkspaceId('home/user/proj'));
  });
});

'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');

// Import internals we want to unit-test directly
const { handleCountTokens } = require('../src/handlers/anthropic');

// We need to test the conversion helpers — expose them by re-requiring the module
// and checking the exported public functions indirectly via integration.
// For pure unit tests of the conversion logic, we import and test the module.

// ── Minimal mock helpers ──

function makeRes() {
  const res = {
    _status: null,
    _headers: {},
    _body: '',
    _ended: false,
    setHeader(k, v) {
      this._headers[k] = v;
    },
    writeHead(code) {
      this._status = code;
    },
    write(chunk) {
      this._body += chunk;
    },
    end(chunk) {
      if (chunk) this._body += chunk;
      this._ended = true;
    },
    get headersSent() {
      return this._status !== null;
    },
    get writableEnded() {
      return this._ended;
    },
  };
  return res;
}

function makeReq(body) {
  const buf = Buffer.from(body);
  const req = {
    headers: {},
    _buf: buf,
    _pos: 0,
    on(event, cb) {
      if (event === 'data') cb(buf);
      if (event === 'end') cb();
      return this;
    },
  };
  return req;
}

// ── Tests ──

describe('handleCountTokens', () => {
