// AG Local Bridge — VS Code Extension
// Exposes Antigravity as a local OpenAI-compatible HTTP API on localhost:11435
//
// Architecture:
//   HTTP server (:11435) → discovers sidecar process → calls sidecar ConnectRPC → returns OpenAI response
//
// The sidecar (language_server_{platform}) runs a ConnectRPC server on a dynamic HTTPS port
// with CSRF tokens. We discover these from the process command line at runtime.
// Binary names: Windows=language_server_windows_x64.exe, macOS=language_server_macos, Linux=language_server_linux_x64

'use strict';

const vscode = require('vscode');
const { createContext } = require('./context');
const { log } = require('./utils');
const httpsInterceptor = require('./interceptors/https');
const httpServerInterceptor = require('./interceptors/http-server');
const h2Interceptor = require('./interceptors/h2');
const { startServer, stopServer } = require('./server');
const { showStatus, diagnoseModels, diagnoseCommands, probeSidecar } = require('./handlers/debug');

/** @type {ReturnType<typeof createContext>} */
let ctx;

// ─────────────────────────────────────────────
// Activation
// ─────────────────────────────────────────────

function activate(context) {
  ctx = createContext();

  ctx.outputChannel = vscode.window.createOutputChannel('AG Local Bridge');
  context.subscriptions.push(ctx.outputChannel);

  // Hook interceptors (must be before sidecar calls)
  httpsInterceptor.install(ctx);
  httpServerInterceptor.install(ctx);
  h2Interceptor.install(ctx);

  ctx.statusBarItem = vscode.window.createStatusBarItem(vscode.StatusBarAlignment.Right, 100);
  ctx.statusBarItem.command = 'agLocalBridge.showStatus';
  ctx.statusBarItem.tooltip = 'Antigravity Bridge — Click for status';
  context.subscriptions.push(ctx.statusBarItem);

  context.subscriptions.push(
    vscode.commands.registerCommand('agLocalBridge.start', () => startServer(ctx)),
    vscode.commands.registerCommand('agLocalBridge.stop', () => stopServer(ctx)),
    vscode.commands.registerCommand('agLocalBridge.showStatus', () => showStatus(ctx)),
    vscode.commands.registerCommand('agLocalBridge.listModels', () => diagnoseModels(ctx)),
    vscode.commands.registerCommand('agLocalBridge.listCommands', () => diagnoseCommands(ctx)),
    vscode.commands.registerCommand('agLocalBridge.probeSidecar', () => probeSidecar(ctx)),
  );

  log(ctx, 'Extension activated. Starting server...');
  startServer(ctx).catch((err) => log(ctx, `Startup error: ${err.message}`, true));

  // Prune stale activeCascades entries every 30 minutes
  const CASCADE_MAX_AGE_MS = 4 * 60 * 60 * 1000; // 4 hours
  const pruneInterval = setInterval(
    () => {
      const cutoff = Date.now() - CASCADE_MAX_AGE_MS;
      let pruned = 0;
      for (const [key, entry] of ctx.activeCascades) {
        if (entry.lastUsed < cutoff) {
          ctx.activeCascades.delete(key);
          pruned++;
        }
      }
      if (pruned > 0) log(ctx, `🧹 Pruned ${pruned} stale cascade(s) from activeCascades`);
    },
    30 * 60 * 1000,
  ); // every 30 minutes
  context.subscriptions.push({ dispose: () => clearInterval(pruneInterval) });
}

function deactivate() {
  httpsInterceptor.uninstall(ctx);
  httpServerInterceptor.uninstall(ctx);
  stopServer(ctx);
}

module.exports = { activate, deactivate };

'use strict';

const vscode = require('vscode');
const fs = require('fs');
const path = require('path');
const { log } = require('./utils');
const { extractText } = require('./images');

// ─────────────────────────────────────────────
// Workspace Detection
// Resolves the workspace directory from the request
// payload, headers, or VS Code workspace folders.
// ─────────────────────────────────────────────

/**
 * Resolve the workspace directory and file URI from the request context.
 *
 * Priority: request body > header > message content heuristics > VS Code workspace
 *
 * @param {object} ctx - Shared context
 * @param {object[]} messages - OpenAI-format messages array
 * @param {object} payload - Parsed request body
 * @param {object} req - HTTP request (for headers)
 * @returns {{ workspaceDir: string|null, workspaceUri: string|null }}
 */
function resolveWorkspace(ctx, messages, payload, req) {
  let workspaceDir = payload.workspace_dir || req.headers['x-workspace-dir'] || null;

  if (!workspaceDir) {
    try {
      // Combine system and user text for keyword/path scanning
      const sysMsgs = messages
        .filter((m) => m.role === 'system')
        .map((m) => extractText(m.content))
        .join('\n');
      const usrMsgs = messages
        .filter((m) => m.role === 'user')
        .map((m) => extractText(m.content))
        .join('\n');
      const allText = sysMsgs + '\n' + usrMsgs;

      // 1. Look for explicit directory mentions from OpenCode/Cursor system prompt
      const explicitMatch = allText.match(
        /(?:working in.*?directory|current workspace|workspace directory).*?([a-zA-Z]:\\[^\s"'>]+)/i,
      );
      if (explicitMatch) {
        const candidate = explicitMatch[1].trim();
        if (fs.existsSync(candidate)) {
          workspaceDir = candidate;
        }
      }

      // 2. Look for .sln absolute paths (common in C# projects if passed in prompt)
      if (!workspaceDir) {
        const slnMatch = allText.match(/([a-zA-Z]:\\[^\s"'>]+\.sln)/i);
        if (slnMatch && fs.existsSync(slnMatch[1])) {
          workspaceDir = path.dirname(slnMatch[1]);
        }
      }

      // 3. Fallback: Score sibling directories by mentions in the text
      if (!workspaceDir) {
        const folders = vscode.workspace.workspaceFolders;
        if (folders && folders.length > 0 && folders[0].uri.scheme === 'file') {
          const currentRoot = folders[0].uri.fsPath;
          const parentDir = path.dirname(currentRoot);
          if (fs.existsSync(parentDir)) {
            const siblings = fs
              .readdirSync(parentDir, { withFileTypes: true })
              .filter((d) => d.isDirectory())
              .map((d) => ({ path: path.join(parentDir, d.name), name: d.name }));

            let bestMatch = null;
            let bestScore = 0;
            for (const { path: p, name } of siblings) {
              if (name.length < 4) continue; // Ignore very short directory names

              // Only match whole words, case-insensitive
              const escapedName = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
              const score = (allText.match(new RegExp(`\\b${escapedName}\\b`, 'gi')) || []).length;
              if (score > bestScore) {
                bestScore = score;
                bestMatch = p;
              }
            }
            if (bestMatch && bestScore > 0) {
              workspaceDir = bestMatch;
              log(ctx, `📂 Guessed workspace from prompt keywords: ${workspaceDir}`);
            }
          }
        }
      }
    } catch (e) {
      log(ctx, `⚠️ Workspace auto-detect failed: ${e.message}`);
    }
  }

  if (!workspaceDir) {
    const folders = vscode.workspace.workspaceFolders;
    if (folders && folders.length > 0 && folders[0].uri.scheme === 'file') {
      workspaceDir = folders[0].uri.fsPath;
    }
  }

  // Convert to file:/// URI format (what the sidecar expects)
  let workspaceUri = null;
  if (workspaceDir) {
    workspaceUri = 'file:///' + workspaceDir.replace(/\\/g, '/');
    log(ctx, `📂 Workspace: ${workspaceDir} -> ${workspaceUri}`);
  } else {
    log(ctx, `⚠️ No workspace dir resolved — Antigravity may pick a random project`);
  }

  return { workspaceDir, workspaceUri };
}

module.exports = { resolveWorkspace };

'use strict';

const { randomUUID } = require('crypto');

/**
 * Shared mutable state for the AG Local Bridge extension.
 *
 * All state that was previously scattered as module-level `let` variables
 * in the monolithic extension.js is consolidated here. A single context
 * object is created in activate() and passed to every module.
 */
function createContext() {
  return {
    // Identity (for Metadata proto payloads)
    sessionId: randomUUID() + Date.now().toString(),
    extensionVersion: '1.1.0',

    // VS Code UI
    /** @type {import('vscode').OutputChannel | null} */
    outputChannel: null,
    /** @type {import('vscode').StatusBarItem | null} */
    statusBarItem: null,

    // HTTP server
    /** @type {import('http').Server | null} */
    server: null,

    // Sidecar discovery cache
    sidecarInfo: null,
    sidecarInfoTimestamp: 0,
    SIDECAR_CACHE_TTL: 300000, // 5 minutes (discovery is expensive on Windows)

    // Concurrency guard
    chatRequestsInFlight: 0,
    MAX_CONCURRENT_REQUESTS: 3,

    // Rate limiting / loop-breaking
    lastResponseTimestamp: 0,
    MIN_REQUEST_INTERVAL_MS: 200, // 200ms cooldown between responses
    lastUserMessageHash: '',
    lastUserMessageTimestamp: 0,
    DEDUP_WINDOW_MS: 1000, // 1s dedup window

    // CSRF token intercepted from Antigravity's own outgoing requests
    interceptedCsrf: null,
    interceptedPort: null,

    // Interceptor originals (stored for uninstall)
    _originalHttpsRequest: null,
    _originalCreateServer: null,

    // H2 interceptor captured payloads
    capturedPayloads: [],
    MAX_CAPTURES: 20,

    // Cascade conversation state
    isWorkspaceSwitching: false,
    activeCascades: new Map(), // convKey -> { id, lastUsed }
    cascadePromises: new Map(), // convKey -> Promise<string>
  };
}

module.exports = { createContext };
